  "settings.commandline.done": "Готово",
  "settings.commandline.trustTitle": "Режим без токена",
  "settings.commandline.trustHint": "Дозволяє інструменту командного рядка підключатися без входу.",
  "settings.commandline.trustCaution": "У цьому режимі будь-яка програма на дозволених комп’ютерах, зокрема агенти, що працюють тут, може керувати Polyth від вашого імені, зокрема схвалювати дії агентів. Запити через зворотний проксі або з браузера ніколи не вважаються довіреними. «Приватна мережа» — це адреси локальної мережі (10.x, 172.16–31.x, 192.168.x), а не діапазони VPN чи оверлеїв.",
