  "shellintro.kicker": "Знайомство з інтерфейсом",
  "shellintro.stepCount": "{step} з {total}",
  "shellintro.steps": "Кроки туру",
  "shellintro.goToStep": "Перейти до кроку {step} з {total}",
  "shellintro.start": "Показати",
  "shellintro.skip": "Пропустити тур",
  "shellintro.finish": "До роботи",
  "shellintro.menuEntry": "Знайомство з інтерфейсом",
  "shellintro.addProjectNow": "Додати проєкт зараз",
  "shellintro.addProjectResumeNote": "Коли закінчите, тур продовжиться.",
  "shellintro.projectReadyTitle": "Ваш проєкт готовий",
  "shellintro.projectReadyBody": "Ось він. Поки його вибрано, нові чати бачать його файли й можуть із ними працювати. Натисніть на проєкт у цьому списку, щоб перемкнутися між ними.",
  "shellintro.projectReadyPhoneBody": "Тепер він у цьому меню. Поки його вибрано, нові чати бачать його файли й можуть із ними працювати. Торкніться тут будь-коли, щоб перемкнути проєкт.",
  "shellintro.openAppearance": "Відкрити «Зовнішній вигляд»",
  "shellintro.welcomeTitle": "Вітаємо в Polyth",
  "shellintro.welcomeBody": "Працювати можна одразу: налаштовувати нічого не треба, а зламати щось не вийде. За хвилину покажемо, де писати, де зберігаються ваші чати і як згодом усе змінити під себе.",
  "shellintro.startTitle": "Почніть просто тут",
  "shellintro.startBody": "Напишіть своїми словами, що потрібно, — запитання, завдання чи чернетку — і надішліть. Відповідь з’явиться тут. Ваші чати бачите тільки ви.",
  "shellintro.projectsTitle": "Чати й проєкти",
  "shellintro.projectsBody": "Тут зберігаються всі ваші чати — до будь-якого можна повернутися. Проєкти, які ви додасте згодом, теж з’являться тут, кожен зі своїми чатами. Маленька крапка означає, що помічник працює або чекає на вашу відповідь.",
  "shellintro.addProjectTitle": "Проєкти — коли знадобляться",
  "shellintro.addProjectBody": "Щоб почати, проєкт не потрібен. Проєкт — це просто папка з вашими файлами: документи, фото, сайт чи код. Додайте її, і помічник зможе відкривати й змінювати ці файли, коли ви попросите. (Розробники можуть також підключити Git-репозиторій або інший комп’ютер через SSH.)",
  "shellintro.topRailTitle": "Інструменти вгорі",
  "shellintro.topRailBody": "Кнопки ваших інструментів. Кожен відкривається поруч із чатом, тож розмова лишається перед очима.",
  "shellintro.rightRailTitle": "Ще інструменти збоку",
  "shellintro.rightRailBody": "Більше інструментів, зокрема з доповнень, які ви встановите. Кожен відкривається бічною панеллю; потягніть її край, щоб зробити ширшою.",
  "shellintro.toolsTitle": "Інструменти",
  "shellintro.dragTitle": "Кнопки — там, де вам зручно",
  "shellintro.dragBody": "Перетягніть кнопку, щоб пересунути її на панелі або на іншу панель. Щоб прибрати, відтягніть її вбік і відпустіть — згодом її можна повернути. На сенсорному екрані спершу натисніть і втримуйте.",
  "shellintro.customizeTitle": "Налаштуйте під себе",
  "shellintro.customizeBody": "Відкрийте меню, на яке вказує стрілка, і ввімкніть «Режим редагування»: на кожній частині екрана з’явиться олівець, щоб додавати, прибирати чи пересувати кнопки й віджети. Решта — у Налаштуваннях: помічники й моделі ШІ, доповнення (пакети) і сполучення клавіш.",
  "shellintro.appearanceTitle": "Вигляд під себе",
  "shellintro.appearanceBody": "У «Налаштування → Зовнішній вигляд» виберіть кольори, світлу чи темну тему, розмір тексту, шрифти, шпалери тощо. Кожному проєкту можна дати власний значок.",
  "shellintro.projectsPhoneTitle": "Чати й проєкти",
  "shellintro.projectsPhoneBody": "Торкніться тут, щоб побачити свої чати. Проєкти, які ви додасте згодом, теж будуть тут. Маленька крапка означає, що помічник працює або чекає на вашу відповідь.",
  "shellintro.addProjectPhoneBody": "Щоб почати, проєкт не потрібен. Проєкт — це просто папка з вашими файлами: документи, фото, сайт чи код. Кнопка + у цьому меню додає її, і тоді помічник зможе відкривати й змінювати ці файли, коли ви попросите.",
  "shellintro.toolsPhoneTitle": "Інструменти",
  "shellintro.toolsPhoneBody": "Тут живуть ваші інструменти. Кожен відкривається на весь екран; кнопка «Назад» повертає до чату.",
  "shellintro.customizePhoneBody": "На комп’ютері «Режим редагування» у вашому меню дає змогу додавати, прибирати й пересувати кнопки. А в Налаштуваннях — і тут — можна вибрати помічників і моделі ШІ, доповнення (пакети) тощо.",
  "composer.manageHarnesses": "Керувати харнесами",
  "packages.onboarding.tours.installed.modelsComeFromHarnesses": "Моделі надходять із ваших харнесів",
  "packages.onboarding.tours.installed.polythTalksToModelsThroughHarnesses": "Polyth спілкується з моделями через харнеси агентів. Безкоштовні моделі OpenCode працюють без облікового запису. Віддаєте перевагу Claude Code, Codex чи іншому агенту? Встановіть і налаштуйте вибрані на сторінці «Харнеси» — це необов’язково.",
  "packages.onboarding.tours.installed.openHarnesses": "Відкрити «Харнеси»",
  "desktopupdate.availableTitle": "Доступна версія Polyth {version}",
  "desktopupdate.availableBody": "Завантажте її зараз. Вона встановиться після перезапуску Polyth.",
  "desktopupdate.manualBody": "Ця збірка оновлюється вручну: завантажте її зі сторінки релізу й встановіть поверх цієї копії.",
  "desktopupdate.downloadingTitle": "Завантаження Polyth {version}…",
  "desktopupdate.downloadingBody": "Працюйте далі. Коли оновлення буде готове, Polyth запропонує перезапуск.",
